# Kaggle script kernel: edgedyn.
import base64, subprocess, sys
open("sweep.py", "wb").write(base64.b64decode(""))
subprocess.run(["pip", "-q", "install", "torch==2.14.0", "--index-url", "https://download.pytorch.org/whl/cpu"])
subprocess.run(["pip", "-q", "install", "expecttest", "hypothesis"])
for attempt in range(80):
    r = subprocess.run([sys.executable, "sweep.py", *['--dynamic', '--dtypes', 'float32,int64,bool'], "--out", "cases.jsonl"], capture_output=True, text=True)
    print(r.stdout[-4000:], flush=True); print("exit", r.returncode, r.stderr[-600:], flush=True)
    if "SWEEP DONE" in r.stdout: break
print("=====JSONL BEGIN", flush=True)
print(open("cases.jsonl").read(), flush=True)
print("=====JSONL END", flush=True)
print("JOB DONE", flush=True)
